static bool digest_is(const void *p,size_t n,const char *hex){uint8_t d[32];DarcCid c;char h[65];darc_sha256(p,n,d);memcpy(c.b,d,32);darc_cid_hex(&c,h);return !strcmp(h,hex);}
static bool buf_hex(const DarcBuf*b,const char*hex){size_t n=strlen(hex);if(n!=b->len*2)return false;static const char x[]="0123456789abcdef";for(size_t i=0;i<b->len;i++)if(hex[2*i]!=x[b->data[i]>>4]||hex[2*i+1]!=x[b->data[i]&15])return false;return true;}
static uint64_t rr(uint64_t x,unsigned n){n&=63u;return n?((x<<n)|(x>>(64u-n))):x;}
static uint64_t rh_ref(const DarcCid*c){uint64_t x=darc_rd_u64(c->b)^darc_rd_u64(c->b+8)^darc_rd_u64(c->b+16)^darc_rd_u64(c->b+24);x^=x>>33;x*=UINT64_C(0xff51afd7ed558ccd);x^=x>>33;x*=UINT64_C(0xc4ceb9fe1a85ec53);x^=x>>33;return x;}

