 DarcParityMember pm[8];uint8_t *chunks[8];DarcBuf pp;for(size_t i=0;i<8;i++){pm[i].len=17+i*13;chunks[i]=malloc((size_t)pm[i].len);for(size_t j=0;j<(size_t)pm[i].len;j++)chunks[i][j]=(uint8_t)(i*29+j*7);darc_object_cid(OBJ_CHUNK,chunks[i],(size_t)pm[i].len,&pm[i].cid);}int pr=darc_parity_build_payload(pm,8,chunks,&pp);DarcStripe ps;DarcBuf parity;bool pok=!pr&&!darc_parity_parse(pp.data,pp.len,&ps,&parity);for(size_t miss=0;miss<8&&pok;miss++){size_t mi=0;while(mi<8&&!darc_cid_eq(&ps.m[mi].cid,&pm[miss].cid))mi++;if(mi==8){pok=false;break;}DarcBuf rrbuf;darc_buf_init(&rrbuf);darc_buf_put(&rrbuf,parity.data,(size_t)ps.m[mi].len);for(size_t j=0;j<8;j++)if(j!=miss)for(size_t x=0;x<rrbuf.len&&x<(size_t)pm[j].len;x++)rrbuf.data[x]^=chunks[j][x];DarcCid got;darc_object_cid(OBJ_CHUNK,rrbuf.data,rrbuf.len,&got);if(!darc_cid_eq(&got,&pm[miss].cid))pok=false;darc_buf_free(&rrbuf);}test_check("ALG-030",pok,"8+1 XOR reconstructs each single member exactly");for(size_t i=0;i<8;i++)free(chunks[i]);darc_buf_free(&pp);darc_buf_free(&parity);
